using System;
using System.Text.Json.Serialization;
using Square.Core.Enum;

namespace Square.Models.Enums;

/// <summary>
/// Defines whether the event was generated by the Square Point of Sale.
/// </summary>
[JsonConverter(typeof(StringEnumConverter<LoyaltyEventSource>))]
public sealed record LoyaltyEventSource : OpenStringEnum<LoyaltyEventSource>
{
    private LoyaltyEventSource(string value) : base(value)
    {
    }

    /// <summary>
    /// The event is generated by the Square Point of Sale (POS).
    /// </summary>
    public static readonly LoyaltyEventSource Square = new("SQUARE");

    /// <summary>
    /// The event is generated by something other than the Square Point of Sale that used the Loyalty API.
    /// </summary>
    public static readonly LoyaltyEventSource LoyaltyApi = new("LOYALTY_API");

    public TResult Match<TResult>(Func<TResult> onSquare,
        Func<TResult> onLoyaltyApi,
        Func<string, TResult> otherwise) =>
        this switch
        {
            _ when this == Square => onSquare(),
            _ when this == LoyaltyApi => onLoyaltyApi(),
            _ => otherwise(Value)
        };

    public void Match(Action onSquare, Action onLoyaltyApi, Action<string> otherwise)
    {
        if (this == Square) onSquare();
        else if (this == LoyaltyApi) onLoyaltyApi();
        else otherwise(Value);
    }
}
